from pathlib import Path
import json, html, shutil, hashlib, re

root=Path(__file__).resolve().parents[1]
out=root/'output/shape-verification'
def read(path):return json.loads(path.read_text(encoding='utf-8'))
unit=read(out/'unit-results.json');assert unit['numTotalTests']==47 and unit['numFailedTests']==0
groups=[('Firebase / พื้นฐาน',root/'output/dev-verification/integration-results.json',6),('Browser / พื้นฐาน',root/'output/dev-verification/ui-results.json',13),('Firebase / BS เดิม',root/'output/bending-verification/bs-integration-results.json',7),('Browser / BS เดิม',root/'output/bending-verification/bs-ui-results.json',8),('Firebase / A4',root/'output/schedule-verification/integration-results.json',7),('Browser / A4',root/'output/schedule-verification/ui-results.json',8),('Firebase / 31/41/44',out/'api-results.json',8),('Browser / 31/41/44',out/'ui-results.json',11)]
reg=out/'regression';reg.mkdir(exist_ok=True)
rows=[]
for label,path,count in groups:
    data=read(path);assert len(data['results'])==count and all(r['status']=='PASS' for r in data['results'])
    if path.parent!=out:
        target=reg/(path.parent.name+'-'+path.name);shutil.copy2(path,target);link=target.relative_to(out).as_posix()
    else:link=path.name
    rows.append(f'<tr><td>{label}</td><td>{count}</td><td class="pass">PASS</td><td><a href="{link}">ผลตรวจ</a></td></tr>')
build=read(out/'build-results.json');a4build=root/'output/schedule-verification/build-browser-results.json';assert build['status']=='PASS' and read(a4build)['status']=='PASS'
shutil.copy2(a4build,reg/'a4-built-results.json')
pdf=read(out/'pdf-verification.json');assert len(pdf['results'])==8 and sum(r['pages'] for r in pdf['results'])==37 and pdf['sourceUnchanged']
regpdf=root/'output/schedule-verification/pdf-verification.json';regleaves=sum(r['pages'] for r in read(regpdf)['results']);assert len(read(regpdf)['results'])==6 and regleaves>=43
shutil.copy2(regpdf,reg/'a4-pdf-verification.json')
checkpoint=root/'output/emulator-checkpoints/v0.8-verified-20261011'
meta=read(checkpoint/'firebase-export-metadata.json')
for key in ['auth','firestore','storage']:
    assert key in meta
    assert (checkpoint/meta[key]['path']).exists()
primary=root/'output/pdf/BS8666-2000-shapes-31-41-44-draft.pdf'
sha=hashlib.sha256(primary.read_bytes()).hexdigest();assert sha==next(r['sha256'] for r in pdf['results'] if r['file']=='v2-frozen-A4.pdf')
summary={'version':'0.8','softwareScenarios':117,'unit':47,'firebase':28,'browser':40,'builtApp':2,'newPDFs':8,'newPDFLeaves':37,'regressionA4PDFs':6,'regressionA4Leaves':regleaves,'initialJavaScriptBytes':build['totalInitialJavaScriptBytes'],'primaryPdfSha256':sha,'sourceUnchanged':True,'checkpointExportMetadataVerified':True,'checkpointReimportTested':False,'engineeringAcceptance':False,'cloudDeployed':False}
(out/'verification-summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
pdfrows=''.join(f'<tr><td><a href="downloads/{r["file"]}">{r["file"]}</a></td><td>{r["size"]}</td><td>{r["pages"]}</td><td><a href="{Path(r["file"]).stem}-contact.png">ภาพทุกแผ่น</a></td></tr>' for r in pdf['results'])
